// Auto-extracted static markup from the original GEMS World Dialogue page.
const pageHtml = "\n<!-- ================= NAV ================= -->\n<header class=\"nav\">\n  <div class=\"nav-inner\">\n    <a class=\"brand\" href=\"/home-page\" aria-label=\"GEMS World Dialogue\">\n      <img class=\"brand-logo\" src=\"/images/gems-logo.png\" alt=\"GEMS World Dialogue\" />\n    </a>\n    <nav class=\"nav-links\">\n      <a href=\"/home-page\" class=\"active\">Home</a>\n      <a href=\"/partners\">Partners</a>\n      <a href=\"/events\">Past Events</a>\n      <a href=\"/subprojects\">Sub-Projects</a>\n      <a href=\"/media\">Media</a>\n    </nav>\n    <div class=\"nav-right\"><a class=\"btn btn-gold btn-sm\" href=\"#connect\">Attend / RSVP</a></div>\n  </div>\n</header>\n<span id=\"top\"></span>\n\n<!-- ================= HERO ================= -->\n<section class=\"hero grad-top\">\n  <div class=\"wrap\">\n    <div class=\"hero-logo reveal\"><img src=\"/images/gems-hero-seal.png\" alt=\"GEMS World Dialogue\" /></div>\n    <div class=\"wordmark reveal\"><div class=\"bh2\">WORLD DIALOGUE <span class=\"dot\">&bull;</span> BEVERLY HILLS</div></div>\n    <div class=\"big-fifty reveal\">50</div>\n    <div class=\"fifty-sub reveal\">Nations &middot; One Pipeline</div>\n    <h1 class=\"reveal\">Dialogue, made <span class=\"gold-text serif\" style=\"font-style:italic;font-weight:600\">visible action.</span></h1>\n    <p class=\"hero-lead reveal\">An international, outcome-driven framework convening power players from fifty nations to accelerate the United Nations Sustainable Development Goals &mdash; advancing the Goals not through statements, but through documented, independently measured action.</p>\n    <div class=\"cta-row reveal\">\n      <a href=\"#about\" class=\"btn btn-teal\">Read the Initiative</a>\n      <a href=\"#connect\" class=\"btn btn-gold\">Express Interest</a>\n    </div>\n    <div class=\"patron-line reveal\">Under the patronage of <b>H.E. Philippe Ziade</b> &mdash; Special Envoy for the State of Nevada to Europe, Africa &amp; the Middle East</div>\n    <div class=\"founders reveal\">\n      <div class=\"f-item\"><div class=\"f-lab\">Convened At</div><div class=\"f-val\">Beverly Hills City Hall</div></div>\n      <div class=\"f-item\"><div class=\"f-lab\">Anchored By</div><div class=\"f-val\">LAU &middot; UN&nbsp;PRME Framework</div></div>\n      <div class=\"f-item\"><div class=\"f-lab\">In Service Of</div><div class=\"f-val\">The 17 Global Goals</div></div>\n    </div>\n  </div>\n</section>\n\n<!-- ================= STAT BAND ================= -->\n<div class=\"statband\">\n  <div class=\"wrap\">\n    <div class=\"stats\">\n      <div class=\"stat reveal\"><div class=\"num gold-text\" data-count=\"17\">17</div><div class=\"lab\">Global Goals</div></div>\n      <div class=\"stat reveal tealstat\"><div class=\"num teal-text\" data-count=\"50\">50</div><div class=\"lab\">Nations Engaged</div></div>\n      <div class=\"stat reveal\"><div class=\"num gold-text\" data-count=\"25\">25</div><div class=\"lab\">Diplomacy Panels</div></div>\n      <div class=\"stat reveal tealstat\"><div class=\"num teal-text\" data-count=\"3\">3</div><div class=\"lab\">Sub-Projects Live</div></div>\n    </div>\n  </div>\n</div>\n\n<!-- ================= THE MANDATE ================= -->\n<section class=\"band-glow\" id=\"mandate\">\n  <div class=\"wrap case\">\n    <div class=\"eyebrow center reveal\">The Mandate</div>\n    <p class=\"big-quote reveal\">A decade after 193 nations pledged seventeen Goals for 2030, fewer than <span class=\"gold-text\">one in five</span> are on track.</p>\n    <p class=\"sub reveal\">A development emergency, in the United Nations' own words. GEMS World Dialogue was established to answer it &mdash; turning pledges into proof, and placing fifty nations on a stage the world is watching. The next five years will decide the next fifty.</p>\n  </div>\n</section>\n\n<!-- ================= WHAT GEMS IS ================= -->\n<section class=\"sec band-deep\" id=\"about\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\" style=\"margin-bottom:44px;max-width:820px\">\n      <div class=\"eyebrow\">The Initiative</div>\n      <h2 class=\"section-title\">Global power players meet &mdash; and <span class=\"gold-text\">action must follow.</span></h2>\n    </div>\n    <div class=\"split\">\n      <div class=\"reveal\">\n        <p class=\"lead\" style=\"margin-bottom:18px\">GEMS &mdash; Global Excellence of Mastery and Success &mdash; is a Beverly Hills&ndash;born initiative established to accelerate the United Nations' seventeen Sustainable Development Goals. Under the motto <b style=\"color:var(--ink)\">&ldquo;Dialogue in Action,&rdquo;</b> it repositions world dialogue from conversation to real-world delivery that can be tracked, tested, and improved.</p>\n        <p class=\"lead\" style=\"margin-bottom:18px\">It was born in Beverly Hills and launched at Beverly Hills City Hall in participation of the Beverly Hills Chamber of Commerce and the Conference &amp; Visitors Bureau &mdash; an American civic home, and a globally recognised address, before it ever crossed a border.</p>\n        <p class=\"lead\">The framework operates under the global patronage of H.E. Philippe Ziade, is anchored academically by the Lebanese American University through the UN-backed PRME framework, and is founded and governed by VIPMINDS in partnership with Growth Holdings, under the executive leadership of Nora Abou Chakra.</p>\n      </div>\n      <div class=\"reveal\">\n        <div class=\"eyebrow\">All Fifty &mdash; None Left Out</div>\n        <div class=\"nations\" id=\"nationsGrid\" aria-hidden=\"true\"></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ================= HOW IT WORKS (5 POINTS) ================= -->\n<section class=\"sec\" id=\"model\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\" style=\"margin-bottom:20px\">\n      <div class=\"eyebrow teal\">How GEMS Works</div>\n      <h2 class=\"section-title\">From pledge to <span class=\"gold-text\">permanent record.</span></h2>\n      <p class=\"lead\" style=\"margin-top:20px\">The framework advances each Goal through five coordinated instruments &mdash; a disciplined progression from mandate to a public, independently evidenced outcome.</p>\n    </div>\n    <div class=\"story-rows\">\n      <div class=\"srow reveal\"><div class=\"sidx gold-text\">01</div><div><h4>The Mandate</h4><p>For each of the seventeen Goals, GEMS runs a dedicated sub-project &mdash; <b>Dialogue in Action</b>, carried out Goal by Goal &mdash; advanced by fifty nations against real, independently evidenced targets.</p></div></div>\n      <div class=\"srow reveal\"><div class=\"sidx gold-text\">02</div><div><h4>Dialogue &amp; Access</h4><p>Under the patronage of H.E. Philippe Ziade, twenty-five panels open working channels between governments &mdash; for cooperation, cultural exchange, and investment.</p></div></div>\n      <div class=\"srow reveal\"><div class=\"sidx gold-text\">03</div><div><h4>Academic Authority</h4><p>Anchored by the Lebanese American University and structured through PRME &mdash; the United Nations' largest alliance with the world's business schools, spanning 800+ institutions across 90+ countries.</p></div></div>\n      <div class=\"srow reveal\"><div class=\"sidx gold-text\">04</div><div><h4>Corporate Engagement</h4><p>A company selects one of the seventeen Goals to champion, activates it through targeted actions, and documents the impact in photographs, film, and data &mdash; earning eligibility for the GEMS Earth Awards.</p></div></div>\n      <div class=\"srow reveal\"><div class=\"sidx gold-text\">05</div><div><h4>The World Stage</h4><p>Each year culminates in a Hollywood documentary with a red-carpet premiere and a GEMS book by Dr. Nehme Azoury (Palgrave Macmillan) &mdash; placing fifty nations' results before the world.</p></div></div>\n    </div>\n  </div>\n</section>\n\n<!-- ================= ACADEMIC RIGOR ================= -->\n<section class=\"sec band-deep\" id=\"rigor\">\n  <div class=\"wrap split\">\n    <div class=\"reveal\">\n      <div class=\"eyebrow teal\">Built on Academic Rigour</div>\n      <h2 class=\"section-title\" style=\"font-size:clamp(28px,3.6vw,42px)\">Accountability, <span class=\"gold-text\">independently verified.</span></h2>\n    </div>\n    <div class=\"reveal\">\n      <p class=\"lead\" style=\"margin-bottom:16px\">GEMS is anchored by the LAU School of Business and its commitment to PRME &mdash; the Principles for Responsible Management Education, the United Nations' accountability framework for business education.</p>\n      <p class=\"lead\" style=\"margin-bottom:22px\">PRME is a rigorous global network of more than 870 signatories across 90 countries, representing over three million students, that mandates absolute transparency. It functions as a technology-backed &ldquo;truth engine,&rdquo; vetting every project against high academic and ethical benchmarks &mdash; a transparent scorecard of deliverables, audited project by project and country by country.</p>\n      <div class=\"facts\">\n        <div class=\"fact\"><span class=\"d\">&#9670;</span><div><b>870+</b> PRME signatories worldwide</div></div>\n        <div class=\"fact\"><span class=\"d\">&#9670;</span><div><b>90+</b> countries represented</div></div>\n        <div class=\"fact\"><span class=\"d\">&#9670;</span><div><b>3M+</b> students within the network</div></div>\n        <div class=\"fact\"><span class=\"d\">&#9670;</span><div><b>Independently</b> audited, project by project</div></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ================= 25 ARENAS ================= -->\n<section class=\"sec\" id=\"pact\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\" style=\"margin-bottom:34px\">\n      <div class=\"eyebrow\">The Global Pact</div>\n      <h2 class=\"section-title\">Diplomacy is the tool. The Goals are the <span class=\"gold-text\">mission.</span></h2>\n      <p class=\"lead\" style=\"margin-top:20px\">The seventeen Sustainable Development Goals define <b style=\"color:var(--ink)\">what</b> the world set out to achieve by 2030. Diplomacy is <b style=\"color:var(--ink)\">how</b> GEMS pursues it. Rather than treat diplomacy as conversation, the Global Pact mobilises twenty-five specialised forms of it as working channels &mdash; the real-world arenas where nations, industries, and visionary minds find common ground, and open the door to cooperation, cultural exchange, and investment.</p>\n      <p class=\"lead\" style=\"margin-top:16px\">Each arena is a route to the Goals. Sport, music, and media carry them to audiences no ministry can reach; economy, capital, and technology fund and build them; health, education, and women's empowerment deliver them directly to people. Grouped into five families and travelled sequentially, panel by panel, the twenty-five arenas turn dialogue into measurable progress across all seventeen Goals.</p>\n    </div>\n\n    <div class=\"reveal arena-cluster\">\n      <div class=\"arena-cluster-head\"><span class=\"acl\">Technology, Science &amp; Security</span><span class=\"acline\"></span></div>\n      <div class=\"arena-grid\">\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">01</span>AI &amp; Technology</div><div class=\"ad\">Aligning artificial intelligence and emerging technology around shared benefit and ethical governance.</div></div>\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">02</span>Science &amp; Innovation</div><div class=\"ad\">Research and discovery as neutral ground &mdash; from quantum to the frontiers of knowledge.</div></div>\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">03</span>Space &amp; Aerospace</div><div class=\"ad\">Cooperation beyond the atmosphere, treating the cosmos as a shared human frontier.</div></div>\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">04</span>Cyber &amp; Data Sovereignty</div><div class=\"ad\">Securing the digital commons &mdash; cybersecurity, privacy, and who governs data across borders.</div></div>\n      </div>\n    </div>\n\n    <div class=\"reveal arena-cluster\">\n      <div class=\"arena-cluster-head teal\"><span class=\"acl\">Economy, Capital &amp; Development</span><span class=\"acline\"></span></div>\n      <div class=\"arena-grid\">\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">05</span>Economic, Trade &amp; Investment</div><div class=\"ad\">Opening markets and directing capital, finance, and venture toward the Goals.</div></div>\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">06</span>Real Estate &amp; Urban Development</div><div class=\"ad\">Building the cities and spaces where communities are meant to thrive.</div></div>\n      </div>\n    </div>\n\n    <div class=\"reveal arena-cluster\">\n      <div class=\"arena-cluster-head\"><span class=\"acl\">Planet &amp; Life</span><span class=\"acline\"></span></div>\n      <div class=\"arena-grid\">\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">07</span>Climate &amp; Energy</div><div class=\"ad\">Accelerating the clean-energy transition and climate resilience, together.</div></div>\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">08</span>Environment &amp; Biodiversity</div><div class=\"ad\">Protecting the ecosystems, oceans, and living world we hold in common.</div></div>\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">09</span>Food &amp; Agriculture</div><div class=\"ad\">Securing nutrition and sustainable food systems for every table.</div></div>\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">10</span>Animal Welfare</div><div class=\"ad\">Advancing the humane treatment and protection of the animal world.</div></div>\n      </div>\n    </div>\n\n    <div class=\"reveal arena-cluster\">\n      <div class=\"arena-cluster-head teal\"><span class=\"acl\">People &amp; Society</span><span class=\"acline\"></span></div>\n      <div class=\"arena-grid\">\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">11</span>Health &amp; Wellbeing</div><div class=\"ad\">Widening access to care and deepening cooperation on global health.</div></div>\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">12</span>Education</div><div class=\"ad\">Carrying quality learning across borders, generation to generation.</div></div>\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">13</span>Women's Empowerment</div><div class=\"ad\">Women leading, and welcomed, at every table of decision.</div></div>\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">14</span>Youth &amp; Next-Generation</div><div class=\"ad\">Placing tomorrow's leaders in today's rooms.</div></div>\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">15</span>Diaspora &amp; Migration</div><div class=\"ad\">Turning global communities into bridges between nations.</div></div>\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">16</span>Happiness</div><div class=\"ad\">Placing human wellbeing and quality of life at the centre of progress.</div></div>\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">17</span>Philanthropy</div><div class=\"ad\">Channelling generosity into structured, lasting impact.</div></div>\n      </div>\n    </div>\n\n    <div class=\"reveal arena-cluster\">\n      <div class=\"arena-cluster-head\"><span class=\"acl\">Culture, Craft &amp; Influence</span><span class=\"acline\"></span></div>\n      <div class=\"arena-grid\">\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">18</span>Cultural</div><div class=\"ad\">Heritage, identity, and mutual understanding carried through culture.</div></div>\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">19</span>Heritage &amp; Regenerative Tourism</div><div class=\"ad\">Travel that restores the places and honours the heritage it visits.</div></div>\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">20</span>Arts</div><div class=\"ad\">The visual and performing arts as a universal language.</div></div>\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">21</span>Music</div><div class=\"ad\">A channel that reaches where words and treaties cannot.</div></div>\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">22</span>Sports</div><div class=\"ad\">The most-watched stage on earth, turned toward statecraft.</div></div>\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">23</span>Media</div><div class=\"ad\">The storytelling that shapes how nations see one another.</div></div>\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">24</span>Fashion &amp; Beauty</div><div class=\"ad\">Design, craft, and self-expression as instruments of soft power.</div></div>\n        <div class=\"arena-item\"><div class=\"an\"><span class=\"anum\">25</span>Luxury</div><div class=\"ad\">Craftsmanship, scarcity, and prestige as vehicles of trust and legacy.</div></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ================= SUB-PROJECTS ================= -->\n<section class=\"sec\" id=\"projects\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\" style=\"margin-bottom:44px;max-width:820px\">\n      <div class=\"eyebrow teal\">Dialogue in Action &middot; The Sub-Projects</div>\n      <h2 class=\"section-title\">A measurable project under each Goal. <span class=\"gold-text\">Three are live today.</span></h2>\n      <p class=\"lead\" style=\"margin-top:20px\">The heart of the model is simple: under the seventeen Goals, GEMS builds dedicated sub-projects with measurable outcomes. Three are already in action &mdash; the School of Life under Quality Education, and, under Gender Equality, two complementary vehicles: WIN, which moves capital and financial knowledge to women, and The Force, which moves visibility and voice to the women and changemakers driving progress.</p>\n    </div>\n\n    <!-- School of Life -->\n    <div class=\"subproject reveal\" id=\"school-of-life\">\n      <div class=\"sp-head\">\n        <div class=\"sdg-badge\"><span class=\"sn\">4</span><span class=\"sl\">SDG</span></div>\n        <div class=\"sp-titles\">\n          <span class=\"sp-status\">Live Now</span>\n          <h3>The School of Life</h3>\n          <div class=\"sp-sub\">SDG 4 &middot; Quality Education</div>\n        </div>\n      </div>\n      <div class=\"sp-body\">\n        <p>There has never been a harder time to be young. This generation is coming of age inside a storm of information, where every question meets a thousand answers and not one arrives with wisdom attached. For all that traditional schools have given, they were never built for this &mdash; they taught the names of rivers and the dates of wars, and sent us into the world fluent in every subject except the one that mattered most: life itself.</p>\n        <p>The School of Life is a one-year online curriculum for ages 15&ndash;17 that teaches what the classroom leaves out &mdash; money, relationships, resilience, and decision-making &mdash; taught beside mentors and peers by life teachers drawn from many fields. It is <b>sequenced, not searchable</b>; <b>practised, not told</b>; and <b>human</b>, because half of who a person becomes at this age is shaped by who is there to see, challenge, and steady them.</p>\n        <p>Built across eight phases &mdash; each a floor the next one stands on &mdash; it launches in Lebanon and extends nation by nation, each with a national President leading local outreach, in partnership with the College of Southern Nevada and featuring a metaverse platform for global access.</p>\n        <div class=\"phases\">\n          <div class=\"phase\"><div class=\"pnum\">0</div><div class=\"ph-t\">Wet Cement</div><div class=\"ph-d\">The twenty-four months that outweigh the next twenty years.</div></div>\n          <div class=\"phase\"><div class=\"pnum\">1</div><div class=\"ph-t\">The Ground Floor</div><div class=\"ph-d\">Master the mind before it masters you.</div></div>\n          <div class=\"phase\"><div class=\"pnum\">2</div><div class=\"ph-t\">Clear Eyes</div><div class=\"ph-d\">Attention, truth &amp; the machines in a world built to blind you.</div></div>\n          <div class=\"phase\"><div class=\"pnum\">3</div><div class=\"ph-t\">The One Body You Get</div><div class=\"ph-d\">Health, choices, and consequences that echo for fifty years.</div></div>\n          <div class=\"phase\"><div class=\"pnum\">4</div><div class=\"ph-t\">Everyone You'll Love or Fight</div><div class=\"ph-d\">People, words &amp; the art of repair.</div></div>\n          <div class=\"phase\"><div class=\"pnum\">5</div><div class=\"ph-t\">When the Money Becomes Yours</div><div class=\"ph-d\">Freedom, traps &amp; standing alone.</div></div>\n          <div class=\"phase\"><div class=\"pnum\">6</div><div class=\"ph-t\">When Things Break</div><div class=\"ph-d\">Mastering the physical world.</div></div>\n          <div class=\"phase\"><div class=\"pnum\">7</div><div class=\"ph-t\">The Fine Print of Being Alive</div><div class=\"ph-d\">Rights, law &amp; staying safe.</div></div>\n          <div class=\"phase\"><div class=\"pnum\">8</div><div class=\"ph-t\">The Summit</div><div class=\"ph-d\">Purpose, discipline &amp; a life's work in the age of machines.</div></div>\n        </div>\n      </div>\n    </div>\n\n    <!-- WIN -->\n    <div class=\"subproject reveal\" id=\"win\">\n      <div class=\"sp-head\">\n        <div class=\"sdg-badge\"><span class=\"sn\">5</span><span class=\"sl\">SDG</span></div>\n        <div class=\"sp-titles\">\n          <span class=\"sp-status\">Live Now</span>\n          <h3>Women-Led Investment Network (WIN)</h3>\n          <div class=\"sp-sub\">SDG 5 &middot; Gender Equality</div>\n        </div>\n      </div>\n      <div class=\"sp-body\">\n        <p>The National Bureau of Economic Research exposed a striking reality: on financial-literacy tests, women answer &ldquo;I don't know&rdquo; far more often than men &mdash; yet when that option is removed, they often choose the correct answer. About a third of the measured gap is not knowledge at all; it is confidence, culturally imposed rather than earned. Say the word &ldquo;investor,&rdquo; and the image that appears is a man in a suit. WIN exists to change both.</p>\n        <div class=\"pullquote teal\">Women lead the table &mdash; and everyone is welcome to take a seat at it.</div>\n        <p>WIN is a GEMS sub-project that pairs a digital educational platform with a private investment network. It teaches the fundamentals of finance and investing &mdash; the lesson most people were never formally taught &mdash; then opens access to real, curated opportunities. A portion of proceeds flows back into community causes through a &ldquo;proceeds loop,&rdquo; so success at the table helps fund good beyond it.</p>\n        <p><b>The model, step by step:</b> Learn a plain-language investing education &rarr; Discover curated opportunities across sectors &rarr; Decide your own entry point, nothing binding &rarr; Give back, as a share of proceeds funds community causes. It is a win for everyone in the circle &mdash; the woman gaining the education, the founder whose project is funded, the investor who sees a return, and the non-profits the proceeds support.</p>\n        <p style=\"margin-bottom:10px\"><b>The Goals it serves:</b></p>\n        <div class=\"sdg-served\" style=\"margin-bottom:20px\">\n          <span class=\"sv\">SDG 5 &middot; Gender Equality</span>\n          <span class=\"sv\">SDG 4 &middot; Quality Education</span>\n          <span class=\"sv\">SDG 8 &middot; Decent Work &amp; Growth</span>\n          <span class=\"sv\">SDG 17 &middot; Partnerships</span>\n        </div>\n        <p><b>The Las Vegas chapter</b> launches under the global framework, built around a Founding Steering Committee &mdash; an elite fifteen-woman leadership infrastructure of strategic connectors and advisors who guide the local ecosystem, connect women seeking investment education, and help identify the non-profits that benefit from the proceeds loop. Two Nevada-focused organisations have been identified as a baseline:</p>\n        <div class=\"facts\">\n          <div class=\"fact\"><span class=\"d\">&#9670;</span><div><b>SafeNest</b> &mdash; Nevada's largest agency providing emergency shelter, legal advocacy, and trauma-informed counselling to end domestic violence.</div></div>\n          <div class=\"fact\"><span class=\"d\">&#9670;</span><div><b>Signs of HOPE</b> &mdash; a Las Vegas non-profit offering help and healing to those affected by sexual violence, with 24/7 crisis support.</div></div>\n        </div>\n\n        <div class=\"event\" style=\"margin-top:26px;margin-bottom:0;background:rgba(6,9,18,0.4)\">\n          <div class=\"ev-top\">\n            <span class=\"ev-tag\">See WIN in Action &middot; Groundwork</span>\n            <span class=\"ev-when\">Thu &middot; Aug 27, 2026 &middot; 7&ndash;10 PM &middot; Otonomus, Las Vegas</span>\n          </div>\n          <h3 style=\"font-size:22px\">Groundwork &mdash; an investor masterclass, showcase &amp; party</h3>\n          <p>WIN's public launch takes the model from page to room in a single evening: a 45-minute plain-language masterclass led by seasoned investors, a showcase of four opportunities across sectors &mdash; from the Otonomus flagship to emerging ventures &mdash; and a celebration through to 10 PM. From curious to invested, in one night. Led by host and patron H.E. Philippe Ziade, with featured investors Alan Amici (CORE Advisory Partners) and Steve Escalante (Otonomus).</p>\n          <div class=\"metarow\" style=\"margin-bottom:0\">\n            <div class=\"m\"><div class=\"ml\">01 &middot; Learn</div><div class=\"mv\">Fundamentals</div></div>\n            <div class=\"m\"><div class=\"ml\">02 &middot; Discover</div><div class=\"mv\">Opportunities</div></div>\n            <div class=\"m\"><div class=\"ml\">03 &middot; Celebrate</div><div class=\"mv\">The Party</div></div>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <!-- The Force -->\n    <div class=\"subproject reveal\" id=\"the-force\">\n      <div class=\"sp-head\">\n        <div class=\"sdg-badge\"><span class=\"sn\">5</span><span class=\"sl\">SDG</span></div>\n        <div class=\"sp-titles\">\n          <span class=\"sp-status\">Live Now &middot; A Dialogue Series with GPW</span>\n          <h3>The Force</h3>\n          <div class=\"sp-sub\">SDG 5 &middot; Gender Equality &mdash; in partnership with Global Powerful Women</div>\n        </div>\n      </div>\n      <div class=\"sp-body\">\n        <p>The Force is a dialogue series about the people bending the world toward something better &mdash; powerful women first, and changemakers of every kind alongside them. Guests are chosen not for their fame but for their impact. Hosted by Rashida Azizi, it gives the changemakers behind the work a voice and carries their stories far beyond the room.</p>\n        <p><b>How it serves the Goal.</b> Where WIN advances Gender Equality through capital and financial literacy, The Force advances it through visibility &mdash; countering the under-representation of women in the stories a society tells about power and progress. By placing women and changemakers at the centre of the frame and measuring their reach, it turns recognition into a lever for SDG 5, in partnership with Global Powerful Women.</p>\n        <div class=\"sdg-served\" style=\"margin-top:6px\">\n          <span class=\"sv\">SDG 5 &middot; Gender Equality</span>\n          <span class=\"sv\">SDG 10 &middot; Reduced Inequalities</span>\n          <span class=\"sv\">SDG 17 &middot; Partnerships</span>\n        </div>\n        <p style=\"margin-top:20px\">Most interviews are two people in two chairs. But The Force is a series of moments one can live &mdash; a swing, a glass of champagne, a game &mdash; each one changing what the guest is able to say. Ten minutes. Six moments. And it never ends on a feeling: every episode closes with one thing that actually happens.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ================= OTONOMUS PARTNERSHIP ================= -->\n<section class=\"sec band-teal\" id=\"otonomus\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\" style=\"margin-bottom:30px;max-width:820px\">\n      <div class=\"eyebrow teal\">A Founding Supporter</div>\n      <h2 class=\"section-title\">Otonomus &mdash; innovation as <span class=\"teal-text\">stewardship.</span></h2>\n      <p class=\"lead\" style=\"margin-top:20px\">Otonomus is the first AI-powered hotel in the world &mdash; a $160M property in Las Vegas that listens, learns, and anticipates, while asking less of the earth in the course of it. Intelligence, applied to a building, becomes stewardship: cleaner energy, lighter consumption, a smaller footprint carried quietly through every day of its operation.</p>\n      <p class=\"lead\" style=\"margin-top:16px\">This is what makes Otonomus a founding supporter of GEMS: it is the clearest proof of the model &mdash; the Goals passing from aspiration into practice inside a single building, while GEMS carries those same Goals across fifty nations. It is diplomacy's answer in built form, advancing SDG 9 above all: innovation and infrastructure in service of people and planet. <b style=\"color:var(--ink)\">One commitment, two arms, a single conviction.</b></p>\n    </div>\n    <div class=\"reveal\" style=\"margin-bottom:24px\">\n      <p style=\"color:var(--muted);font-size:13px;margin-bottom:10px\"><b style=\"color:var(--ink)\">The Goals it advances:</b></p>\n      <div class=\"sdg-served\">\n        <span class=\"sv\">SDG 9 &middot; Industry, Innovation &amp; Infrastructure</span>\n        <span class=\"sv\">SDG 7 &middot; Affordable &amp; Clean Energy</span>\n        <span class=\"sv\">SDG 11 &middot; Sustainable Cities</span>\n        <span class=\"sv\">SDG 13 &middot; Climate Action</span>\n      </div>\n    </div>\n    <div class=\"event reveal\" style=\"margin-bottom:0\">\n      <div class=\"ev-top\">\n        <span class=\"ev-tag\">Hosted at Otonomus &middot; Programme of Visit</span>\n        <span class=\"ev-when\">30 July &ndash; 2 August 2026</span>\n      </div>\n      <h3 style=\"font-size:22px\">Delegation of Mercedes-Benz Stadium</h3>\n      <div class=\"ev-where\">Otonomus Hotel &middot; Las Vegas</div>\n      <p>Facilitated by GEMS World Dialogue, the delegation of Mercedes-Benz Stadium (Atlanta, Georgia) is received at Otonomus for a reception, an address by H.E. Philippe Ziade on the technology of a building that learns, a guided walkthrough, and a closing group photograph &mdash; a working exchange between two institutions carrying the same Goals.</p>\n    </div>\n  </div>\n</section>\n\n<!-- ================= PANELS / CONVENINGS ================= -->\n<section class=\"sec\" id=\"panels\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\" style=\"margin-bottom:44px;max-width:820px\">\n      <div class=\"eyebrow teal\">Upcoming Diplomacy Panels</div>\n      <h2 class=\"section-title\">Sport, capital, and culture, <span class=\"teal-text\">turned to statecraft.</span></h2>\n      <p class=\"lead\" style=\"margin-top:20px\">These are the twenty-five arenas in action. Across 2026, GEMS convenes its diplomacy panels &mdash; each one opening working channels between governments, industries, and the individuals who move them.</p>\n    </div>\n\n    <!-- Sports Diplomacy -->\n    <div class=\"event reveal\">\n      <div class=\"ev-top\">\n        <span class=\"ev-tag\">Beyond the Octagon &middot; Sports Diplomacy</span>\n        <span class=\"ev-when\">Las Vegas &middot; 2026</span>\n      </div>\n      <h3>Beyond the Octagon</h3>\n      <div class=\"ev-where\">Worre Studios &middot; Las Vegas</div>\n      <p>Soft power, statecraft, and the most-watched force in the world today &mdash; a landmark gathering from the fight capital of the planet. In June 2026, a UFC Octagon rose on the White House lawn, and the President walked out beside Dana White. Sport is no longer entertainment; it is power. When a fighter walks to the Octagon, more of humanity is watching than for almost any moment on earth &mdash; across 170 countries, in dozens of languages, all at once.</p>\n      <div class=\"metarow\">\n        <div class=\"m\"><div class=\"ml\">Countries Watching</div><div class=\"mv\">170+</div></div>\n        <div class=\"m\"><div class=\"ml\">Nations Spend to Host</div><div class=\"mv\">Billions</div></div>\n        <div class=\"m\"><div class=\"ml\">In the Front Row</div><div class=\"mv\">Presidents</div></div>\n      </div>\n      <div class=\"eyebrow\" style=\"margin-top:28px\">The Flashpoints &mdash; Questions That Change Everything</div>\n      <div class=\"flashlist\">\n        <div class=\"flash\"><div class=\"fn\">1</div><div><div class=\"ft\">The Fighter Who Out-Diplomats the Diplomat</div><div class=\"fd\">How one athlete shifts a nation's image faster than an entire foreign ministry.</div></div></div>\n        <div class=\"flash\"><div class=\"fn\">2</div><div><div class=\"ft\">Why Nations Are Buying Fights</div><div class=\"fd\">The billions the Gulf spends on combat sport &mdash; and the influence they are really purchasing.</div></div></div>\n        <div class=\"flash\"><div class=\"fn\">3</div><div><div class=\"ft\">From Banned to the White House</div><div class=\"fd\">How a sport once outlawed as barbaric became a fixture of presidential power.</div></div></div>\n        <div class=\"flash\"><div class=\"fn\">4</div><div><div class=\"ft\">The Cage as Neutral Ground</div><div class=\"fd\">Sworn rivals share a card and a broadcast &mdash; and sport does what treaties cannot.</div></div></div>\n        <div class=\"flash\"><div class=\"fn\">5</div><div><div class=\"ft\">Your Favourite Fighter Is a Foreign Policy</div><div class=\"fd\">The athlete as a country's most-watched ambassador.</div></div></div>\n        <div class=\"flash\"><div class=\"fn\">6</div><div><div class=\"ft\">The Next Superpower Is a Gym</div><div class=\"fd\">Africa, the Gulf, and Southeast Asia &mdash; where combat sport plants the next flag.</div></div></div>\n        <div class=\"flash\"><div class=\"fn\">7</div><div><div class=\"ft\">What the State Department Could Learn</div><div class=\"fd\">Reach, loyalty, and storytelling &mdash; lessons in real influence from the fastest-growing sport on earth.</div></div></div>\n      </div>\n    </div>\n\n    <!-- Two-up smaller panels -->\n    <div class=\"grid-2\">\n      <div class=\"event reveal\" style=\"margin-bottom:0\">\n        <div class=\"ev-top\"><span class=\"ev-tag\">Luxury Diplomacy</span></div>\n        <h3 style=\"font-size:22px\">The Luxury Panel</h3>\n        <div class=\"ev-where\">Closed-Door Studio Production</div>\n        <p>The Luxury Diplomacy track examines ultra-luxury, absolute scarcity, and uncompromising craftsmanship as a language of soft power &mdash; where hyper-value assets become a shared culture between nations, establishing trust, prestige, and generational legacy across sovereign borders.</p>\n      </div>\n      <div class=\"event reveal\" style=\"margin-bottom:0\">\n        <div class=\"ev-top\"><span class=\"ev-tag\">Music Diplomacy</span><span class=\"ev-when\">May 2, 2026 &middot; 6:00 PM</span></div>\n        <h3 style=\"font-size:22px\">The Music Panel</h3>\n        <div class=\"ev-where\">WePlay Studios</div>\n        <p>A high-production convening on music as a channel of cultural diplomacy &mdash; one of the twenty-five arenas through which GEMS opens working channels between nations, industries, and audiences.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ================= GEMS EARTH AWARDS ================= -->\n<section class=\"sec awards\" id=\"awards\">\n  <div class=\"wrap\">\n    <div class=\"free-badge reveal\">&#9670; Participation is free &middot; Submission is free</div>\n    <div class=\"reveal\" style=\"max-width:820px;margin:0 auto\">\n      <div class=\"eyebrow center teal\">The Flagship &mdash; A Celebration of Collective Impact</div>\n      <h2 class=\"section-title\">The GEMS <span class=\"gold-text\">Earth Awards.</span></h2>\n      <p class=\"lead\" style=\"margin:22px auto 0;text-align:center\">At the heart of the movement is a simple, hopeful idea: that we share one planet, and that its future is built by ordinary people choosing to care. Across fifty nations, companies and the people within them adopt a Goal and bring it to life &mdash; a seminar, a clean-up, a meal provided, a hand extended &mdash; each act a small light switched on for the world we hold in common.</p>\n      <p class=\"lead\" style=\"margin:16px auto 0;text-align:center\">The Earth Awards gather those lights into one celebration. Every contribution, however modest, is honoured alongside the world's &mdash; recorded, recognised, and woven into a shared story of what humanity can do when it acts together. Not a competition, and not marketing: a global thank-you to everyone helping carry the seventeen Goals forward.</p>\n    </div>\n    <div class=\"lifecycle\" style=\"margin-top:48px;text-align:left\">\n      <div class=\"step reveal\"><div class=\"sn gold-text\">01</div><h4>Select &amp; Align</h4><p>The company chooses one of the seventeen Sustainable Development Goals to champion for the year.</p></div>\n      <div class=\"step reveal\"><div class=\"sn gold-text\">02</div><h4>Activate</h4><p>It outlines and runs distinct actions that put the Goal into practice through its own people.</p></div>\n      <div class=\"step reveal\"><div class=\"sn gold-text\">03</div><h4>Validate Impact</h4><p>It submits proof &mdash; photographs, film, and quantitative data &mdash; measured against LAU's standard of genuine accountability.</p></div>\n    </div>\n    <p class=\"reveal\" style=\"text-align:center;color:var(--muted-2);font-size:13px;font-style:italic;margin-top:34px;max-width:720px;margin-left:auto;margin-right:auto\">An illustrative example: a company selects SDG 2 &mdash; Zero Hunger, and outlines three actions: a staff seminar on food waste, meals provided through a local food bank, and a weekly donation of unused cafeteria food to a shelter &mdash; validated with photographs, film, and data such as 200 employees engaged and 800 meals donated.</p>\n  </div>\n</section>\n\n<!-- ================= GOVERNANCE ================= -->\n<section class=\"sec\" id=\"governance\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\" style=\"margin-bottom:44px;max-width:820px\">\n      <div class=\"eyebrow teal\">Governance &amp; Patronage</div>\n      <h2 class=\"section-title\">Guided by <span class=\"gold-text\">global voices.</span></h2>\n      <p class=\"lead\" style=\"margin-top:20px\">GEMS World Dialogue is a corporate initiative jointly led by two registered entities &mdash; Growth Holdings and VIPMINDS &mdash; and directed by an advisory board presided over by Dr. Nehme Azoury (USEK), bridging enterprise, academia, diplomacy, and philanthropy across four continents.</p>\n    </div>\n    <div class=\"board-grid\" id=\"boardGrid\"></div>\n  </div>\n</section>\n\n<!-- ================= LEGACY ================= -->\n<section class=\"sec band-deep\" id=\"legacy\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal center\" style=\"text-align:center;margin:0 auto 44px;max-width:760px\">\n      <div class=\"eyebrow center teal\">How It Is Remembered</div>\n      <h2 class=\"section-title\">A year of work, made <span class=\"teal-text\">permanent.</span></h2>\n      <p class=\"lead\" style=\"margin:20px auto 0\">At year's end, every activation across all fifty nations is consolidated into three monumental media properties &mdash; one prestige legacy that endures, and a reason for every nation and company that took part to be seen.</p>\n    </div>\n    <div class=\"legacy\">\n      <div class=\"lc reveal\"><div class=\"ic gold-text\">&#10070;</div><h3>The GEMS World Book</h3><p>A prestigious global publication featuring power players from over fifty nations, authored by Dr. Nehme Azoury and published by Palgrave Macmillan.</p></div>\n      <div class=\"lc reveal\"><div class=\"ic teal-text\">&#9654;</div><h3>The Documentary Feature</h3><p>A high-production cinematic documentary slated for global streaming &mdash; premiering in Hollywood on a red carpet.</p></div>\n      <div class=\"lc reveal\"><div class=\"ic teal-text\">&#9672;</div><h3>The Guinness World Record</h3><p>A sanctioned attempt for the longest human chain video in history &mdash; a continuous relay of participants passing a global diplomacy pact across some fifty nations.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- ================= STAND WITH THE MISSION ================= -->\n<section class=\"sec\" id=\"support\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\" style=\"margin-bottom:20px;max-width:820px\">\n      <div class=\"eyebrow\">Stand With the Mission</div>\n      <h2 class=\"section-title\">Your place in <span class=\"gold-text\">the work.</span></h2>\n      <p class=\"lead\" style=\"margin-top:20px\">GEMS World Dialogue is a running global movement connecting diplomacy, world power players, and everyday citizens in service of the seventeen Goals. Supporters take their place across three history-making milestones &mdash; the GEMS World Book, the documentary, and the Guinness World Record chain. Not a purchase; a place in the work.</p>\n    </div>\n    <div class=\"support-table reveal\">\n      <a class=\"support-row\" href=\"https://payment.gemsworlddialogue.com/?tier=supporter\">\n        <div class=\"st-l\"><div class=\"st-name\">Supporter</div><div class=\"st-price\">$60<small>/yr</small></div></div>\n        <div class=\"st-r\">A supporter badge and a certificate of appreciation signed by GEMS leadership &mdash; your name counted among those carrying the dialogue forward.</div>\n      </a>\n      <a class=\"support-row\" href=\"https://payment.gemsworlddialogue.com/?tier=friends\">\n        <div class=\"st-l\"><div class=\"st-name\">GEMS Friends</div><div class=\"st-price\">$120<small>/yr</small></div></div>\n        <div class=\"st-r\">Everything above, plus a digital copy of the GEMS 2027 Book and your photograph in the Global Mosaic Artwork featured on the CNN digital campaign.</div>\n      </a>\n      <a class=\"support-row\" href=\"https://payment.gemsworlddialogue.com/?tier=catalyst\">\n        <div class=\"st-l\"><div class=\"st-name\">The Catalyst</div><div class=\"st-price\">$1,500<small>/yr</small></div></div>\n        <div class=\"st-r\">A print copy of the GEMS 2027 Book and a feature inside the official GEMS Documentary.</div>\n      </a>\n      <a class=\"support-row\" href=\"https://payment.gemsworlddialogue.com/?tier=legacy\">\n        <div class=\"st-l\"><div class=\"st-name\">Diplomacy Legacy</div><div class=\"st-price\">$5,000<small>/yr</small></div></div>\n        <div class=\"st-r\">Digital and print editions of the Book, an official Co-Builder end-credit in the documentary, a place in the Guinness World Record chain, and credit across post-win global press releases.</div>\n      </a>\n      <a class=\"support-row\" href=\"https://payment.gemsworlddialogue.com/?tier=patron\">\n        <div class=\"st-l\"><div class=\"st-name\">The Patron</div><div class=\"st-price\">$25,000<small>/yr</small></div></div>\n        <div class=\"st-r\">Title-card billing in the documentary, a syndicated wire headline to AP, Reuters, Bloomberg and AFP, a Times Square spotlight during launch week, a dedicated two-page editorial spread, two VIP red-carpet premiere passes, and a custom media kit.</div>\n      </a>\n    </div>\n    <div class=\"reveal\" style=\"margin-top:30px;display:flex;gap:22px;flex-wrap:wrap\">\n      <div class=\"card\" style=\"flex:1;min-width:280px\"><span class=\"diamond\">&#9670;</span><h3 style=\"margin-top:12px\">Gift the Legacy</h3><p>Place the name of a child, mentor, or family member in the history books and media credits instead of your own.</p></div>\n      <div class=\"card\" style=\"flex:1;min-width:280px\"><span class=\"diamond\">&#9670;</span><h3 style=\"margin-top:12px\">The Silent Link</h3><p>Remain entirely private. Receive a uniquely numbered Digital Diplomatic Passport confirming your place among the links in the chain, without any public attribution.</p></div>\n    </div>\n    <div class=\"reveal\" style=\"text-align:center;margin-top:36px\">\n      <a href=\"#connect\" class=\"btn btn-gold\">Secure Your Place</a>\n    </div>\n  </div>\n</section>\n\n<!-- ================= LAUNCH VOICES ================= -->\n<section class=\"sec band-deep\" id=\"voices\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal\" style=\"margin-bottom:34px\">\n      <div class=\"eyebrow\">Distinguished Voices at the Launch</div>\n      <h2 class=\"section-title\">Convened at <span class=\"gold-text\">Beverly Hills City Hall.</span></h2>\n      <p class=\"lead\" style=\"margin-top:20px\">GEMS was launched in participation of the Beverly Hills Chamber of Commerce and the Conference &amp; Visitors Bureau, with distinguished voices from government, academia, and industry.</p>\n    </div>\n    <div class=\"grid-3\" id=\"voicesGrid\"></div>\n  </div>\n</section>\n\n<!-- ================= PROPOSE / OPEN CALL ================= -->\n<section class=\"sec\" id=\"propose\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal center\" style=\"text-align:center;margin:0 auto 34px;max-width:760px\">\n      <div class=\"eyebrow center teal\">The Door Is Open</div>\n      <h2 class=\"section-title\">Have an idea, a suggestion, or a partnership in mind? <span class=\"gold-text\">We'd love to hear it.</span></h2>\n      <p class=\"lead\" style=\"margin:20px auto 0\">No idea is too early, and no thought too small. Whatever you're imagining &mdash; a project, a partnership, or a spark you can't quite shake &mdash; just tell us in your own words. A real person on the GEMS team reads every message that comes in.</p>\n    </div>\n\n    <div class=\"formcard reveal\" style=\"max-width:720px\">\n      <form id=\"ideaForm\" novalidate>\n        <div class=\"frow\">\n          <div class=\"field\"><label>Your Name</label><input type=\"text\" name=\"iname\" placeholder=\"Your name\" required></div>\n          <div class=\"field\"><label>Email</label><input type=\"email\" name=\"iemail\" placeholder=\"you@example.com\" required></div>\n        </div>\n        <div class=\"field full\" style=\"margin-bottom:24px\">\n          <label>What's on your mind?</label>\n          <textarea name=\"idea\" id=\"ideaText\" style=\"min-height:150px\" placeholder=\"Tell us what you're thinking&hellip;\"></textarea>\n        </div>\n        <button type=\"submit\" class=\"btn btn-gold\" style=\"width:100%\">Send It Our Way</button>\n        <div class=\"form-success\" id=\"ideaSuccess\">Thank you &mdash; it's in front of the GEMS team now. If it moves the mission forward, we'll be in touch to build it with you.</div>\n        <div class=\"idea-cta\">Good ideas rarely arrive on schedule. Bring yours whenever it does.</div>\n      </form>\n    </div>\n  </div>\n</section>\n\n<!-- ================= CONTACT ================= -->\n<section class=\"sec band-glow\" id=\"connect\">\n  <div class=\"wrap\">\n    <div class=\"sec-head reveal center\" style=\"text-align:center;margin:0 auto 40px;max-width:720px\">\n      <div class=\"eyebrow center\">Expression of Interest</div>\n      <h2 class=\"section-title\">Open a channel with <span class=\"gold-text\">GEMS World Dialogue.</span></h2>\n      <p class=\"lead\" style=\"margin:20px auto 0\">Whether you represent a government, an institution, or a company &mdash; or come as a student, an individual, or a member of the media &mdash; and wish to stand with the mission, the GEMS team will be in touch to discuss how you might take part.</p>\n    </div>\n    <div class=\"formcard reveal\">\n      <form id=\"gemsForm\" novalidate>\n        <div class=\"frow\">\n          <div class=\"field\"><label>Full Name</label><input type=\"text\" name=\"name\" placeholder=\"Your name\" required></div>\n          <div class=\"field\"><label>Organisation</label><input type=\"text\" name=\"org\" placeholder=\"Company / Institution\"></div>\n        </div>\n        <div class=\"frow\">\n          <div class=\"field\"><label>Title / Role</label><input type=\"text\" name=\"title\" placeholder=\"Your title\"></div>\n          <div class=\"field\"><label>Email</label><input type=\"email\" name=\"email\" placeholder=\"you@example.com\" required></div>\n        </div>\n        <div class=\"frow\">\n          <div class=\"field\"><label>Country</label><input type=\"text\" name=\"country\" placeholder=\"Country\"></div>\n          <div class=\"field\"><label>You are writing as&hellip;</label>\n            <select name=\"interest\">\n              <option value=\"\">Select one</option>\n              <option>A government or diplomatic partner</option>\n              <option>An institution, foundation or NGO</option>\n              <option>A company &mdash; GEMS Earth Awards / Corporate Engagement</option>\n              <option>An investor &mdash; the WIN Network</option>\n              <option>An individual supporter</option>\n              <option>Media / press</option>\n            </select>\n          </div>\n        </div>\n        <div class=\"field full\" style=\"margin-bottom:24px\">\n          <label>Message</label>\n          <textarea name=\"message\" placeholder=\"Tell us how you would like to take part\"></textarea>\n        </div>\n        <div class=\"checks\">\n          <label class=\"check\"><input type=\"checkbox\" name=\"updates\"><span>Please keep me informed of future panels and partnership opportunities.</span></label>\n          <label class=\"check\"><input type=\"checkbox\" name=\"consent\"><span>I consent to GEMS World Dialogue contacting me regarding this enquiry.</span></label>\n        </div>\n        <button type=\"submit\" class=\"btn btn-gold\" style=\"width:100%\">Submit Expression of Interest</button>\n        <div class=\"form-success\" id=\"formSuccess\">Thank you &mdash; your message has reached the GEMS team. We will be in touch shortly.</div>\n        <p class=\"form-note\">This form is ready to connect to your GEMS handler, CRM, or secure checkout.</p>\n      </form>\n    </div>\n  </div>\n</section>\n\n<!-- ================= FOOTER ================= -->\n<footer>\n  <div class=\"wrap\">\n    <div class=\"femblem\"><img src=\"/images/gems-logo.png\" alt=\"GEMS World Dialogue\" /></div>\n    <a class=\"fmail\" href=\"mailto:info@gemsworlddialogue.com\">info@gemsworlddialogue.com</a>\n    <div class=\"flinks\">\n      <a href=\"#about\">The Initiative</a><a href=\"#projects\">Sub-Projects</a><a href=\"#panels\">Panels</a><a href=\"#awards\">Earth Awards</a><a href=\"#governance\">Governance</a><a href=\"/events\">Past Events</a><a href=\"/media\">Media</a><a href=\"/partners\">Partners</a><a href=\"#connect\">Contact</a>\n    </div>\n    <div class=\"tag\">Beverly Hills to the World</div>\n    <p class=\"fine\">GEMS World Dialogue is an independent, outcome-driven initiative advancing the United Nations Sustainable Development Goals through the UN PRME framework via its partnership with the Lebanese American University. It is not a United Nations body and does not present itself as one. All frameworks, intellectual property, and brand assets are wholly owned and governed under VIPMINDS, in partnership with Growth Holdings, under the patronage of H.E. Philippe Ziade. VIPMINDS Communications Agency &middot; Beverly Hills, CA &amp; Las Vegas, NV.</p>\n  </div>\n</footer>\n\n";

